import React from "react";
import {
  FaBolt,
  FaUserGraduate,
  FaLeaf,
  FaBrain,
  FaTrophy,
  FaProjectDiagram,
  FaCalendarAlt,
  FaPalette
} from "react-icons/fa";

const Projects = () => {
  return (
    <section className="network-page">

      {/* TITLE */}
      <div className="header">
        <h1>My System <span>Network</span></h1>
        <p>Projects + Achievements visualized as connected intelligence nodes</p>
      </div>

      {/* NETWORK */}
      <div className="network">

        {/* CONNECTION LINES (VISUAL ONLY) */}
        <div className="line l1"></div>
        <div className="line l2"></div>
        <div className="line l3"></div>
        <div className="line l4"></div>

        {/* CENTER NODE */}
        <div className="node center">
          <FaBrain />
          <h3>Cogni Core</h3>
          <p>My Thinking System</p>
        </div>

        {/* PROJECT NODES */}
        <div className="node p1">
          <FaBolt />
          <h4>EnergyPulse</h4>
          <span>React Dashboard</span>
        </div>

        <div className="node p2">
          <FaUserGraduate />
          <h4>Student Portal</h4>
          <span>Full Stack System</span>
        </div>

        <div className="node p3">
          <FaLeaf />
          <h4>Farm2Fork</h4>
          <span>Frontend UI</span>
        </div>

        {/* ACHIEVEMENTS NODES */}
        <div className="node a1">
          <FaTrophy />
          <h4>SIH 2025</h4>
          <span>Hackathon</span>
        </div>

        <div className="node a2">
          <FaProjectDiagram />
          <h4>Best Project</h4>
          <span>Li-Fi Innovation</span>
        </div>

        <div className="node a3">
          <FaCalendarAlt />
          <h4>Code Crunch</h4>
          <span>Event Host</span>
        </div>

        <div className="node a4">
          <FaPalette />
          <h4>Event Coord.</h4>
          <span>Leadership</span>
        </div>

      </div>

      {/* STYLE */}
      <style>{`

        .network-page {
          min-height: 100vh;
          padding: 60px 10%;
          background: radial-gradient(circle at top, #0b1220, #050816);
          color: white;
          font-family: "Poppins", sans-serif;
          overflow: hidden;
        }

        /* HEADER */
        .header {
          text-align: center;
          margin-bottom: 50px;
        }

        .header h1 {
          font-size: 42px;
        }

        .header span {
          color: #38BDF8;
        }

        .header p {
          color: #94a3b8;
        }

        /* NETWORK AREA */
        .network {
          position: relative;
          width: 100%;
          height: 600px;
        }

        /* CENTER NODE */
        .center {
          position: absolute;
          top: 50%;
          left: 50%;
          transform: translate(-50%, -50%);
          background: rgba(56,189,248,0.1);
          border: 1px solid #38BDF8;
          box-shadow: 0 0 25px rgba(56,189,248,0.4);
          z-index: 5;
        }

        .center svg {
          font-size: 28px;
          color: #38BDF8;
        }

        /* NODES */
        .node {
          position: absolute;
          width: 120px;
          padding: 10px;
          border-radius: 14px;
          text-align: center;
          background: rgba(255,255,255,0.04);
          border: 1px solid rgba(56,189,248,0.2);
          transition: 0.3s;
        }

        .node:hover {
          transform: scale(1.1);
          box-shadow: 0 0 20px rgba(56,189,248,0.3);
        }

        .node svg {
          color: #38BDF8;
          font-size: 20px;
          margin-bottom: 5px;
        }

        .node h4 {
          font-size: 13px;
          margin: 0;
          color: #38BDF8;
        }

        .node span {
          font-size: 11px;
          color: #94a3b8;
        }

        /* PROJECT POSITIONS */
        .p1 { top: 20%; left: 20%; }
        .p2 { top: 10%; right: 20%; }
        .p3 { bottom: 20%; left: 25%; }

        /* ACHIEVEMENT POSITIONS */
        .a1 { bottom: 10%; right: 20%; }
        .a2 { top: 35%; right: 5%; }
        .a3 { top: 35%; left: 5%; }
        .a4 { bottom: 35%; left: 5%; }

        /* LINES (NEURAL CONNECTIONS) */
        .line {
          position: absolute;
          background: rgba(56,189,248,0.15);
        }

        .l1 {
          width: 2px;
          height: 300px;
          top: 20%;
          left: 50%;
        }

        .l2 {
          width: 300px;
          height: 2px;
          top: 50%;
          left: 20%;
        }

        .l3 {
          width: 300px;
          height: 2px;
          top: 50%;
          right: 20%;
        }

        .l4 {
          width: 2px;
          height: 300px;
          bottom: 20%;
          left: 50%;
        }

        /* MOBILE */
        @media (max-width: 900px) {
          .network {
            height: auto;
            display: flex;
            flex-wrap: wrap;
            justify-content: center;
            gap: 20px;
          }

          .node {
            position: relative;
            width: 45%;
          }

          .center {
            position: relative;
            transform: none;
          }

          .line {
            display: none;
          }
        }

      `}</style>

    </section>
  );
};

export default Projects;
